cat(sprintf("stat_julia_terms = [%s]\n", strs(julia_terms)))
cat(sprintf("statistics = [%s]\n", num(as.numeric(stats))))
cat("\n# --- (ii) directed MPLE --------------------------------------------------\n")
cat(sprintf("mple_term_names = [%s]\n", strs(names(coef(fit)))))
cat('mple_julia_terms = ["WithinLayer(Edges(), [1, 2])", "WithinLayer(Mutual(), [1, 2])", "WithinLayer(GWESP(0.5), [1, 2])", "WithinLayer(NodeMatch(:grp), [1, 2])", "InterlayerDependence(1, 2)"]\n')
cat(sprintf("mple_coefficients = [%s]\n", num(mple_coef)))
